SELECT CASE WHEN 10 > ANY (SELECT * FROM (SELECT 5 v FROM DUAL UNION ALL SELECT 20 v FROM DUAL))
            THEN 'TRUE' ELSE 'FALSE' END
FROM DUAL;

SELECT CASE WHEN 10 > ALL (SELECT * FROM (SELECT 5 v FROM DUAL UNION ALL SELECT 20 v FROM DUAL))
            THEN 'TRUE' ELSE 'FALSE' END
FROM DUAL;

SELECT COUNT(*)
FROM (SELECT 1 id FROM DUAL UNION ALL SELECT 2 id FROM DUAL) t
WHERE id NOT IN (
  SELECT id FROM (
    SELECT 1 id FROM DUAL UNION ALL SELECT CAST(NULL AS NUMBER) id FROM DUAL
  )
);

WITH nums AS (
  SELECT 1 n FROM DUAL UNION ALL SELECT 2 n FROM DUAL UNION ALL SELECT 3 n FROM DUAL
)
SELECT SUM(n) FROM nums;
